#include <string>
#include <queue>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int kSimilarity(string s1, string s2) {
        if (s1 == s2) return 0;

        queue<pair<string, int>> q;
        unordered_set<string> visited;
        q.push({s1, 0});
        visited.insert(s1);

        while (!q.empty()) {
            auto [cur, step] = q.front(); q.pop();
            int i = 0;
            while (cur[i] == s2[i]) ++i;
            for (int j = i + 1; j < cur.size(); ++j) {
                if (cur[j] == s2[i] && cur[j] != s2[j]) {
                    swap(cur[i], cur[j]);
                    if (cur == s2) return step + 1;
                    if (!visited.count(cur)) {
                        q.push({cur, step + 1});
                        visited.insert(cur);
                    }
                    swap(cur[i], cur[j]);
                }
            }
        }

        return -1;
    }
};
